.[CUSTOMER_CODE] AS CUSTOMER_CODE_01, [SHIP_TO_CUSTOMER_ID_001].[CUSTOMER_NAME] AS CUSTOMER_NAME_01, [SALES_ORDER_DOC_SD].[SHIP_TO_ADDR_NAME] AS SHIP_TO_ADDR_NAME_01, [SALES_ORDER_DOC_SD].[SHIP_TO_CONTACT_NAME] AS SHIP_TO_CONTACT_NAME_01, [DELIVERY_TERM_ID_001].[DELIVERY_TERM_CODE] AS DELIVERY_TERM_CODE_01, [DELIVERY_TERM_ID_001].[DELIVERY_TERM_DESCRIPTION] AS DELIVERY_TERM_DESCRIPTION_01, [SALES_ORDER_DOC_SD].[BUSINESS_QTY] AS BUSINESS_QTY_01, [SALES_ORDER_DOC_SD].[PRICE_QTY] AS PRICE_QTY_01, [SALES_ORDER_DOC_SD].[INVENTORY_QTY] AS INVENTORY_QTY, [SALES_ORDER_DOC_SD].[SECOND_QTY] AS SECOND_QTY, [SALES_ORDER_DOC_SD].[PLAN_DELIVERY_DATE] AS PLAN_DELIVERY_DATE_01, [SALES_ORDER_DOC_SD].[PLAN_SHIP_DATE] AS PLAN_SHIP_DATE, [SALES_ORDER_DOC_SD].[DELIVERY_TYPE] AS DELIVERY_TYPE, [SALES_ORDER_DOC_SD].[DELIVERY_PARTNER_ID_RTK] AS DELIVERY_PARTNER_ID_RTK, [SALES_ORDER_DOC_SD].[DELIVERY_PARTNER_ID_ROid] AS DELIVERY_PARTNER_ID_ROid, CASE [SALES_ORDER_DOC_SD].[DELIVERY_PARTNER_ID_RTK] WHEN N'PLANT' THEN [PLANT].[PLANT_CODE] WHEN N'SUPPLIER' THEN [SUPPLIER].[SUPPLIER_CODE] ELSE N'' END AS CalColumn_01, CASE [SALES_ORDER_DOC_SD].[DELIVERY_PARTNER_ID_RTK] WHEN N'PLANT' THEN [PLANT].[PLANT_NAME] WHEN N'SUPPLIER' THEN [SUPPLIER].[SUPPLIER_NAME] ELSE N'' END AS CalColumn_02, [DELIVERY_PLANT_ID].[PLANT_CODE] AS PLANT_CODE, [DELIVERY_PLANT_ID].[PLANT_NAME] AS PLANT_NAME, [DELIVERY_WAREHOUSE_ID].[WAREHOUSE_CODE] AS WAREHOUSE_CODE, [DELIVERY_WAREHOUSE_ID].[WAREHOUSE_NAME] AS WAREHOUSE_NAME, CASE [SALES_ORDER_DOC_SD].[SYNERGY_SOURCE_ID_RTK] WHEN N'SALES_SYNERGY' THEN [SYNERGY_SOURCE_ID_SALES_SYNERGY].[SALES_SYNERGY_CODE] WHEN N'SUPPLY_SYNERGY' THEN [SYNERGY_SOURCE_ID_SUPPLY_SYNERGY].[SUPPLY_SYNERGY_CODE] ELSE N'' END AS SALES_SYNERGY_CODE, CASE [SALES_ORDER_DOC_SD].[SYNERGY_SOURCE_ID_RTK] WHEN N'SALES_SYNERGY' THEN [SYNERGY_SOURCE_ID_SALES_SYNERGY].[SALES_SYNERGY_NAME] WHEN N'SUPPLY_SYNERGY' THEN [SYNERGY_SOURCE_ID_SUPPLY_SYNERGY].[SUPPLY_SYNERGY_NAME] ELSE N'' END AS SALES_SYNERGY_NAME, [