.[CASH_DISCOUNT_DUE_DATE1] AS CASH_DISCOUNT_DUE_DATE1, [SALES_ORDER_DOC_INSTAL].[CASH_DISCOUNT_RATE2] AS CASH_DISCOUNT_RATE2, [SALES_ORDER_DOC_INSTAL].[CASH_DISCOUNT_DUE_DATE2] AS CASH_DISCOUNT_DUE_DATE2, [SALES_ORDER_DOC_INSTAL].[CASH_DISCOUNT_RATE3] AS CASH_DISCOUNT_RATE3, [SALES_ORDER_DOC_INSTAL].[CASH_DISCOUNT_DUE_DATE3] AS CASH_DISCOUNT_DUE_DATE3, [TAX_ID_01].[TAX_CODE] AS TAX_CODE_01, [TAX_ID_01].[TAX_NAME] AS TAX_NAME_01, [SALES_ORDER_DOC_INSTAL].[TAX_RATE] AS TAX_RATE_01, [SALES_ORDER_DOC_INSTAL].[TAX_INCLUDED] AS TAX_INCLUDED_01, [SALES_ORDER_DOC_INSTAL].[AMT_UNINCLUDE_TAX_OC] AS AMT_UNINCLUDE_TAX_OC_01, [SALES_ORDER_DOC_INSTAL].[TAX_OC] AS TAX_OC_02, [SALES_ORDER_DOC_INSTAL].[PRE_SETTLEMENT_AMT_UN_TAX_OC] AS PRE_SETTLEMENT_AMT_UN_TAX__01, [SALES_ORDER_DOC_INSTAL].[PRE_SETTLEMENT_TAX_OC] AS PRE_SETTLEMENT_TAX_OC_01, [SALES_ORDER_DOC_INSTAL].[OFFSETED_AMT_UN_TAX_OC] AS OFFSETED_AMT_UN_TAX_OC, [SALES_ORDER_DOC_INSTAL].[OFFSETED_TAX_OC] AS OFFSETED_TAX_OC, [SETT_COMPANY_ID].[COMPANY_CODE] AS COMPANY_CODE_01, [SETT_COMPANY_ID].[COMPANY_NAME] AS COMPANY_NAME_01, CASE [ITEM_ID].[DRAWING_NO_FROM] WHEN N'1' THEN [ITEM_ID].[DRAWING_NO] WHEN N'2' THEN [ITEM_FEATURE_ID].[DRAWING_NO] END AS DRAWING_NO, [ITEM_FEATURE_ID].[ITEM_SPECIFICATION] AS ITEM_FEATURE_SPECIFICATION, [PROJECT_ID].[PROJECT_CODE] AS PROJECT_CODE, [PROJECT_ID].[PROJECT_NAME] AS PROJECT_NAME FROM [SALES_ORDER_DOC] AS [SALES_ORDER_DOC] LEFT JOIN [SALES_CENTER] AS [SALES_CENTER] ON [SALES_ORDER_DOC].[Owner_Org_ROid] = [SALES_CENTER].[SALES_CENTER_ID] LEFT JOIN [DOC] AS [DOC] ON [SALES_ORDER_DOC].[DOC_ID] = [DOC].[DOC_ID] LEFT JOIN [CUSTOMER] AS [CUSTOMER_ID] ON [SALES_ORDER_DOC].[CUSTOMER_ID] = [CUSTOMER_ID].[CUSTOMER_BUSINESS_ID] LEFT JOIN [EMPLOYEE] AS [EMPLOYEE] ON [SALES_ORDER_DOC].[Owner_Emp] = [EMPLOYEE].[EMPLOYEE_ID] LEFT JOIN [ADMIN_UNIT] AS [ADMIN_UNIT] ON [SALES_ORDER_DOC].[Owner_Dept] = [ADMIN_UNIT].[ADMIN_UNIT_ID] LEFT JOIN [COMPANY] AS [SETTLEMENT_COMPANY_ID] ON [SALES_ORDER_DOC].[SETTLEMENT_COMPANY_ID] = [SETTLEMENT_COMPANY_ID].[COMPANY_ID] LEFT JOIN [CURRENCY] AS [CURRENCY_ID] ON [SALES_ORDER_DOC].[CURRENCY_ID] = [CURRENCY_ID].[CURRENCY_ID] LEFT JOIN [PAYMENT_TERM] AS [PAYMENT_TERM_ID] ON [SALES_ORDER_DOC].[PAYMENT_TERM_ID] = [PAYMENT_TERM_ID].[PAYMENT_TERM_ID] LEFT JOIN [CONTRACT] AS [CONTRACT_ID] ON [SALES_ORDER_DOC].[CONTRACT_ID] = [CONTRACT_ID].[CONTRACT_ID] LEFT JOIN [DELIVERY_TERM] AS [DELIVERY_TERM_ID] ON [SALES_ORDER_DOC].[DELIVERY_TERM_ID] = [DELIVERY_TERM_ID].[DELIVERY_TERM_ID] LEFT JOIN [CUSTOMER] AS [INVOICE_CUSTOMER_ID] ON [SALES_ORDER_DOC].[INVOICE_CUSTOMER_ID] = [INVOICE_CUSTOMER_ID].[CUSTOMER_BUSINESS_ID] LEFT JOIN [TAX_INVOICE_CATEGORY] AS [TAX_INVOICE_CATEGORY_ID] ON [SALES_ORDER_DOC].[TAX_INVOICE_CATEGORY_ID] = [TAX_INVOICE_CATEGORY_ID].[TAX_INVOICE_CATEGORY_ID] LEFT JOIN [SALES_ORDER_DOC_D] AS [SALES_ORDER_DOC_D] ON [SALES_ORDER_DOC].[SALES_ORDER_DOC_ID] = [SALES_ORDER_DOC_D].[SALES_ORDER_DOC_ID] LEFT JOIN [ITEM] AS [ITEM_ID] ON [SALES_ORDER_DOC_D].[ITEM_ID] = [ITEM_ID].[ITEM_BUSINESS_ID] LEFT JOIN [ITEM_FEATURE] AS [ITEM_FEATURE_ID] ON [SALES_ORDER_DOC_D].[ITEM_FEATURE_ID] = [ITEM_FEATURE_ID].[ITEM_FEATURE_ID] LEFT JOIN [UNIT] AS [BUSINESS_UNIT_ID] ON [SALES_ORDER_DOC_D].[BUSINESS_UNIT_ID] = [BUSINESS_UNIT_ID].[UNIT_ID] LEFT JOIN [UNIT] AS [PRICE_UNIT_ID] ON [SALES_ORDER_DOC_D].[PRICE_UNIT_ID] = [PRICE_UNIT_ID].[UNIT_ID] LEFT JOIN [TAX] AS [TAX_ID] ON [SALES_ORDER_DOC_D].[TAX_ID] = [TAX_ID].[TAX_ID] LEFT JOIN [QUOTATION_D] AS [QUOTATION_D] ON ( [SALES_ORDER_DOC_D].[SOURCE_ID_RTK] = 'QUOTATION.QUOTATION_D' AND [SALES_ORDER_DOC_D].[SOURCE_ID_ROid] = [QUOTATION_D].[QUOTATION_D_ID] ) LEFT JOIN [QUOTATION] AS [QUOTATION] ON [QUOTATION_D].[QUOTATION_ID] = [QUOTATION].[QUOTATION_ID] LEFT JOIN [CONTRACT_SD] AS [CONTRACT_SD] ON ( [SALES_ORDER_DOC_D].[SOURCE_ID_RTK] = 'CONTRACT.CONTRACT_D.CONTRACT_SD' AND [SALES_ORDER_DOC_D].[SOURCE_ID_ROid] = [CONTRACT_SD].[CONTRACT_SD_ID] ) LEFT JOIN [CONTRACT_D] AS [CONTRACT_D] ON [CONTRACT_SD].[CONTRACT_D_ID] = [CONTRACT_D].[CONTRACT_D_ID] LEFT JOIN [CONTRACT] AS [CONTRACT] ON [CONTRACT_D].[CONTRACT_ID] = [CONTRACT].[CONTRACT_ID] LEFT JOIN [CUSTOMER_ITEM] AS [CUSTOMER_ITEM_ID] ON [SALES_ORDER_DOC_D].[CUSTOMER_ITEM_ID] = [CUSTOMER_ITEM_ID].[CUSTOMER_ITEM_ID] INNER JOIN ( SELECT [CUSTOMER].[CUSTOMER_BUSINESS_ID] AS [CUSTOMER_ID], N'' AS [CUSTOMER_F1], N'' AS [CUSTOMER_F2], N'' AS [CUSTOMER_F3] FROM [CUSTOMER] UNION ALL ( SELECT '00000000-0000-0000-0000-000000000000' AS [CUSTOMER_ID], N'' AS [CUSTOMER_F1], N'' AS [CUSTOMER_F2], N'' AS [CUSTOMER_F3] ) ) AS [CUSTOMER_PROPERTY] ON [SALES_ORDER_DOC].[CUSTOMER_ID] = [CUSTOMER_PROPERTY].[CUSTOMER_ID] INNER JOIN ( SELECT [ITEM].[ITEM_BUSINESS_ID] AS [ITEM_ID], ISNULL( [ITEM_FEATURE].[ITEM_FEATURE_ID], '00000000-0000-0000-0000-000000000000' ) AS [ITEM_FEATURE_ID], N'' AS [ITEM_F1], N'' AS [ITEM_F2], N'' AS [ITEM_F3], N'' AS [ITEM_F4] FROM [ITEM] AS [ITEM] LEFT OUTER JOIN [ITEM_FEATURE] AS [ITEM_FEATURE] ON [ITEM].[ITEM_BUSINESS_ID] = [ITEM_FEATURE].[ITEM_BUSINESS_ID] UNION ALL ( SELECT '00000000-0000-0000-0000-000000000000' AS [ITEM_ID], '00000000-0000-0000-0000-000000000000' AS [ITEM_FEATURE_ID], N'' AS [ITEM_F1], N'' AS [ITEM_F2], N'' AS [ITEM_F3], N'' AS [ITEM_F4] ) ) AS [FEATURE] ON ( [SALES_ORDER_DOC_D].[ITEM_ID] = [FEATURE].[ITEM_ID] AND [SALES_ORDER_DOC_D].[ITEM_FEATURE_ID] = [FEATURE].[ITEM_FEATURE_ID] ) LEFT JOIN [SALES_ORDER_DOC_SD] AS [SALES_ORDER_DOC_SD] ON [SALES_ORDER_DOC_D].[SALES_ORDER_DOC_D_ID] = [SALES_ORDER_DOC_SD].[SALES_ORDER_DOC_D_ID] LEFT JOIN [CUSTOMER] AS [SHIP_TO_CUSTOMER_ID_001] ON [SALES_ORDER_DOC_SD].[SHIP_TO_CUSTOMER_ID] = [SHIP_TO_CUSTOMER_ID_001].[CUSTOMER_BUSINESS_ID] LEFT JOIN [DELIVERY_TERM] AS [DELIVERY_TERM_ID_001] ON [SALES_ORDER_DOC_SD].[DELIVERY_TERM_ID] = [DELIVERY_TERM_ID_001].[DELIVERY_TERM_ID] LEFT JOIN [PLANT] AS [PLANT] ON ( [SALES_ORDER_DOC_SD].[DELIVERY_PARTNER_ID_ROid] = [PLANT].[PLANT_ID] AND [SALES_ORDER_DOC_SD].[DELIVERY_PARTNER_ID_RTK] = 'PLANT' ) LEFT JOIN [SUPPLIER] AS [SUPPLIER] ON ( [SALES_ORDER_DOC_SD].[DELIVERY_PARTNER_ID_ROid] = [SUPPLIER].[SUPPLIER_BUSINESS_ID] AND [SALES_ORDER_DOC_SD].[DELIVERY_PARTNER_ID_RTK] = 'SUPPLIER' ) LEFT JOIN [PLANT] AS [DELIVERY_PLANT_ID] ON [SALES_ORDER_DOC_SD].[DELIVERY_PLANT_ID] = [DELIVERY_PLANT_ID].[PLANT_ID] LEFT JOIN [WAREHOUSE] AS [DELIVERY_WAREHOUSE_ID] ON [SALES_ORDER_DOC_SD].[DELIVERY_WAREHOUSE_ID] = [DELIVERY_WAREHOUSE_ID].[WAREHOUSE_ID] LEFT JOIN [SALES_SYNERGY] AS [SYNERGY_SOURCE_ID_SALES_SYNERGY] ON ( [SALES_ORDER_DOC_SD].[SYNERGY_SOURCE_ID_ROid] = [SYNERGY_SOURCE_ID_SALES_SYNERGY].[SALES_SYNERGY_ID] AND [SALES_ORDER_DOC_SD].[SYNERGY_SOURCE_ID_RTK] = 'SALES_SYNERGY' ) LEFT JOIN [SUPPLY_SYNERGY] AS [SYNERGY_SOURCE_ID_SUPPLY_SYNERGY] ON ( [SALES_ORDER_DOC_SD].[SYNERGY_SOURCE_ID_ROid] = [SYNERGY_SOURCE_ID_SUPPLY_SYNERGY].[SUPPLY_SYNERGY_ID] AND [SALES_ORDER_DOC_SD].[SYNERGY_SOURCE_ID_RTK] = 'SUPPLY_SYNERGY' ) LEFT JOIN [SUPPLY_CENTER] AS [SUPPLY_CENTER_ID] ON [SALES_ORDER_DOC_SD].[SUPPLY_CENTER_ID] = [SUPPLY_CENTER_ID].[SUPPLY_CENTER_ID] LEFT JOIN [SALES_ORDER_DOC_INSTAL] AS [SALES_ORDER_DOC_INSTAL] ON ( 0 = 1 AND [SALES_ORDER_DOC].[SALES_ORDER_DOC_ID] = [SALES_ORDER_DOC_INSTAL].[SALES_ORDER_DOC_ID] ) LEFT JOIN [PAYMENT_TERM] AS [PAYMENT_TERM_ID_01] ON [SALES_ORDER_DOC_INSTAL].[PAYMENT_TERM_ID] = [PAYMENT_TERM_ID_01].[PAYMENT_TERM_ID] LEFT JOIN [TAX] AS [TAX_ID_01] ON [SALES_ORDER_DOC_INSTAL].[TAX_ID] = [TAX_ID_01].[TAX_ID] LEFT JOIN [COMPANY] AS [SETT_COMPANY_ID] ON [SALES_ORDER_DOC_SD].[SETT_COMPANY_ID] = [SETT_COMPANY_ID].[COMPANY_ID] LEFT JOIN [PROJECT] AS [PROJECT_ID] ON [SALES_ORDER_DOC_D].[PROJECT_ID] = [PROJECT_ID].[PROJECT_ID] WHERE [SALES_CENTER].[SALES_CENTER_ID] = '35ee06fa-265d-44c3-8813-1712b767c6d1'
AND [SALES_ORDER_DOC].[DOC_NO] like concat('%', #{doc_NO}, '%')
AND [ITEM_ID].[ITEM_CODE] = #{item_CODE}
AND [SALES_ORDER_DOC_SD].[CLOSE] = #{doc_SD_CLOSE}
AND [SALES_ORDER_DOC].ApproveStatus = #{approveStatus}
AND ORDER_DATE >= #{params.beginTime}
AND ORDER_DATE <= #{params.endTime}
ORDER BY ORDER_DATE DESC, DOC_NO ASC, SequenceNumber ASC
